"""Frozen arithmetic and admissibility checks for the approved fresh contrast."""
from pathlib import Path
import json,math
q=json.loads(Path('final_qualification.json').read_text()); anchorA=json.loads(Path('base384_1000.json').read_text());anchorB=json.loads(Path('base384_2000.json').read_text());fineB=json.loads(Path('fine512.json').read_text());out=[]
for S,filename,anchor,cal in [(1000,'production1000.json',anchorA,q['S1000_fine']),(2000,'production2000.json',anchorB,q['S2000_fine'])]:
 r=json.loads(Path(filename).read_text());R=r['metrics']['normalized_flux_slope'];cad=max(abs(v/R-1) for v in r['cadence_rate_interval']);path=abs(r['rate_other_path']/R-1);base_terms=cal['terms'];mesh=base_terms['mesh'];cfl=base_terms['CFL'];direct=mesh+cfl+cad+path;Ra=anchor['metrics']['normalized_flux_slope']
 if S==1000:
  Rf=Ra;uf=cal['u'];gridshift=0.;anchorshift=abs(Ra-R);transport=(Rf*uf+anchorshift)/R+max(0,cad-cal['terms']['cadence'])
 else:
  Rf=fineB['metrics']['normalized_flux_slope'];uf=cal['u'];gridshift=abs(Rf-Ra);anchorshift=abs(Ra-R);transport=(Rf*uf+gridshift+anchorshift)/R+max(0,cad-cal['terms']['cadence'])
 u=max(.01,direct,transport);inv=r['full_domain_null_inventory'];highindex=next(i for i,row in enumerate(r['timeseries']) if row['reconnected_flux_from_by']>=.05);counts=sorted(set((sum(p[2]=='X' for p in row['nulls']),sum(p[2]=='O' for p in row['nulls'])) for row in inv));minrho=min(row['density_min'] for row in r['extended_timeseries']);minp=min(row['pressure_min'] for row in r['extended_timeseries'])
 checks={'complete_window':r['checks']['flux_window_reached'],'runtime_representation':r['checks']['representation'],'runtime_physics_controls':r['checks']['physics_controls'],'divergence':r['metrics']['max_abs_divb']<1e-9,'boundary':r['metrics']['max_boundary_normal_fraction']<.05,'mass':r['conservation']['mass_max_relative_drift']<1e-6,'energy':r['conservation']['energy_max_relative_drift']<.01,'positive_margin':minrho>1e-10 and minp>1e-10,'single_sheet_saved_fields':counts==[(1,2)],'actual_bracket_covered':inv[-1]['index']==highindex,'qualified_fine_mesh_gate':cal['mesh_gate'],'rate_uncertainty':u<=.15}
 out.append({'S_eta':S,'rate':R,'t_low':r['metrics']['flux_low_crossing_time'],'t_high':r['metrics']['flux_high_crossing_time'],'relative_uncertainty':u,'rate_interval':[R*(1-u),R*(1+u)],'terms':{'direct_mesh':mesh,'direct_cadence':cad,'direct_path':path,'direct_CFL':cfl,'direct_sum':direct,'fine_absolute_allowance':Rf*uf,'absolute_grid_shift':gridshift,'absolute_fresh_anchor_shift':anchorshift,'transport_relative':transport},'admissibility':checks,'admissibility_values':{'min_density':minrho,'min_pressure':minp,'max_divb':r['metrics']['max_abs_divb'],'max_boundary_normal_fraction':r['metrics']['max_boundary_normal_fraction'],'mass_relative_drift':r['conservation']['mass_max_relative_drift'],'energy_relative_drift':r['conservation']['energy_max_relative_drift'],'topology_counts':counts,'topology_frames':len(inv),'upper_bracket_index':highindex,'upper_bracket_time':r['timeseries'][highindex]['time'],'upper_bracket_flux':r['timeseries'][highindex]['reconnected_flux_from_by']},'config':r['config'],'provenance':r['provenance']})
a,b=out;den=math.log(2);p=math.log(b['rate']/a['rate'])/den;lower=math.log(b['rate_interval'][0]/a['rate_interval'][1])/den;upper=math.log(b['rate_interval'][1]/a['rate_interval'][0])/den
result={'cases':out,'contrast':[1000,2000],'p_eff':p,'numerical_interval':[lower,upper],'root_band':[-.55,-.45],'all_admissibility_checks':all(all(v['admissibility'].values()) for v in out),'interval_disjoint_from_band':upper<-.55 or lower>-.45,'status':'Arithmetic check; scientific disposition requires independent review of fresh evidence receipts.'}
Path('contrast.json').write_text(json.dumps(result,indent=2,allow_nan=False)+'\n');print(json.dumps(result))
